    { const y = RT + 1.6; LBox(g, 30, 3.6, 11, -10, y, 16, GL); LBox(g, 36, 0.6, 16, -10, y + 3.6, 16, CON); const Ac = []; for (let x = -27; x <= 7; x += 4) for (const z of [9, 23]) bxT(Ac, x, y, z, 0.4, 3.6, 0.4, 0); flush(g, Ac, CON); }
