          const ya = Math.max(a[2] - 0.35, 0.3), yb = Math.max(b[2] - 0.35, 0.3), dx = x1 - x0, dz = z1 - z0, l = Math.hypot(dx, dz) || 1, nx = -dz/l, nz = dx/l;
